// TH14 synthetic appearance aliases used by this card (subset of transcribe/th14/touhou-bullets.ecl).
// TH14 native type -> target slot: 0..23 same, 24..42 shifted by +1. source stays "th14".
const TH14_BALL2: int = 432;   // native type 5 (Card02Head etSprite(1, 5, 6))
const TH14_RICE: int = 480;    // native type 8 (BossCard2_at3 etSprite(0, 8, 4))

// TH14 v1.00b st02bs.ecl::BossCard2 -> single-attack training card (spell 2).
// Source entry st02bs.ecl.txt:623-717; dependencies :719-742 (BossCard2_at),
// :744-774 (BossCard2_at2), :776-794 (BossCard2_at3), :1171-1202 (Card02Head).
// Exit context st02bs.ecl.txt:420-452 (Boss3): timeout/hp interrupt at 2280 -> clear.
// Boss entry state from st02bs.ecl.txt:10-54 (Boss): movePos(0,128), lifeSet(1900),
// hurtbox 40 / hitbox 48, moveLimit not modelable (target has no persistent limit API).

const TIME_LIMIT: int = 2764;        // 120 opening + 2280 source timer + 360 tail + 4 spawn allowance
const OPENING_BUFFER: int = 120;

const SOURCE_TIMEOUT: int = 2280;    // :643 setInterrupt(0, 0, 2280, "Boss3")
const G_LZ: int = 16;                // globals free segment: laser handle ring
const LZ_PER_HEAD: int = 6;          // 3 volleys x 2 rods, covers all live rods of one head
const LZ_RING: int = 54;             // 9 heads x 6 slots

// Card02Head bullets: :753 etEx(1,0,2,1,...) ANIM (birth stage omitted, 4*speed setback kept)
// then :762 etExSet(1,1,0,4,120,-999999,1/60,%A) ACCEL fixed direction for 120 frames.
xformdef BULLET_CURVE(acc_dir: angle) {
    @120 set_gravity(0.0166667fx * cos(acc_dir), 0.0166667fx * sin(acc_dir));
    set_gravity(0fx, 0fx);
}

// ---------------------------------------------------------------------------
// Card02Head (:1171-1202), one enemy per head; I0/F0/F1 arrive by value because
// the source reads them from the parent's I0/F0/F1 snapshot at enmCreate.
// ---------------------------------------------------------------------------
async sub head(slot: int, dir: angle, speed: fx) {
    set_invuln(65535);                     // training shell: enemy cannot be shot down
    set_hurtbox(7fx);                      // :1177 setHurtbox(14,14) -> radius 7
    set_hitbox(6fx);                       // :1178 setHitbox(12,12) -> body radius 6
    move_vel(0, -90deg, 0.75fx, EASE_LINEAR);   // :1182 moveVel(-pi/2, 0.75)
    wait(60);                              // :1183
    move_speed(0, 0fx, EASE_LINEAR);       // :1184 moveSpeed(0)
    wait(60);                              // :1185
    move_vel(0, dir, speed, EASE_LINEAR);  // :1186 moveVel(F0, F1)
    move_speed(60, 0fx, EASE_QUAD_OUT);    // :1187 moveSpeedTime(60, 4, 0)
    spawn laser_loop(slot);                // :1189 BossCard2_at() async
    spawn bullet_loop();                   // :1190 BossCard2_at2() async
    loop { wait(60); }                     // :1191-1195 wait(60) loop
}

// BossCard2_at (:719-742): aimed pair of Line rods every 100 frames.
async sub laser_loop(slot: int) {
    wait(40);                              // :722
    var k: int = 0;
    loop {
        var a: angle = aim_player();       // :732 %A = %ANGLE_PLAYER
        // :727-729 laserNew(0,0,128,0,14) + etSprite/etAngle/etSpeed; Line judgement
        // segment = 0.8L long, origin advanced by 0.1L (shared TH16 line formula),
        // width 14 -> half height 14/4 = 3.5 -> target width 7.
        var h1: int = laser(1, $self_x + 8fx * cos(a + 90deg),
                            $self_y + 8fx * sin(a + 90deg),
                            a, 115.2fx, 7fx, 0, 220, 0);
        lz_start(h1, 12.8fx);
        lz_speed(h1, 3fx, 102.4fx);
        var h2: int = laser(1, $self_x + 8fx * cos(a - 90deg),
                            $self_y + 8fx * sin(a - 90deg),
                            a, 115.2fx, 7fx, 0, 220, 0);
        lz_start(h2, 12.8fx);
        lz_speed(h2, 3fx, 102.4fx);
        var base: int = G_LZ + slot * LZ_PER_HEAD + (k % 3) * 2;
        set_global(base, h1);
        set_global(base + 1, h2);
        k = k + 1;
        wait(100);                         // :738
    }
}

// BossCard2_at2 (:744-774): 15 back-fired, player-curving bullets, then 320 idle frames.
async sub bullet_loop() {
    wait(40);                              // :754
    loop {
        for j in 0..15 {                   // :758 $C = 15
            var aim: angle = aim_player(); // :761/:763 ANGLE_PLAYER read at emission
            // :761/:762 ACCEL direction: ANGLE_PLAYER + RANDRAD/6
            var acc: angle = aim + (((rand(65536) - 32768) / 6) as angle);
            // :763/:764 initial direction: ANGLE_PLAYER + pi + RANDRAD/8 (fired away)
            var ang: angle = aim + 180deg + (((rand(65536) - 32768) / 8) as angle);
            // :765 RANDF2 in [-1,1): etSpeed(1, 1 + RANDF2*0.2)
            var u: fx = ((rand(65536) - 32768) as fx) / 256fx / 128fx;   // (rv-32768)/32768 in [-1,1)
            var spd: fx = 1fx + u * 0.2fx;
            // :753 ANIM a=1 birth setback position -= 4*velocity
            var sx: fx = $self_x - 4fx * spd * cos(ang);
            var sy: fx = $self_y - 4fx * spd * sin(ang);
            _ = fire(TH14_BALL2, 6, sx, sy, spd, ang, BULLET_CURVE(acc), none);
            wait(2);                       // :767
        }
        wait(320);                         // :770
    }
}

// BossCard2_at3 (:776-794) on the boss itself: 64-way fixed ring when the player is
// within 96px. Emission polls every 20 frames until the 2280 timeout.
async sub at3_loop() {
    sh_reset(0);
    sh_sprite(0, TH14_RICE, 4);            // :780 etSprite(0, 8, 4)
    sh_ring(0, 1);                         // :779 etAim(0, 3) fixed-direction ring
    sh_aim(0, 0);
    sh_count(0, 64, 1);                    // :781
    sh_angle(0, 0deg, 0deg);               // :782
    sh_speed(0, 1.5fx, 0fx);               // :783
    sh_dist(0, -6fx);                      // :784 ANIM a=1: 4 * 1.5 px setback
    for i in 0..102 {                      // checks at boss t = 251, 271, ... 2271
        if dist($player_x - $self_x, $player_y - $self_y) < 96fx {   // :787
            sh_fire(0);                    // :788
        }
        wait(20);                          // :790
    }
}

// ---------------------------------------------------------------------------
// BossCard2 (:623-717) carried by the real boss enemy.
// ---------------------------------------------------------------------------
async sub boss_main() {
    set_invuln(65535);                     // training shell: enemy cannot be shot down
    set_hitbox(24fx);                      // Boss(): setHitbox(48,48) -> body radius 24
    set_hurtbox(20fx);                     // Boss(): setHurtbox(40,40) -> radius 20
    for i in 0..LZ_RING { set_global(G_LZ + i, -1); }
    // :635-637 moveVel/moveVelTime/movePosTime zero resets are no-ops at rest (entry is static).
    move_to(40, 0fx, 144fx, EASE_QUAD_OUT);    // :651 movePosTime(40, 4, 0, 144)
    wait(40);                              // :652
    wait(90);                              // :654 (EffChargePoint3 visual omitted)
    wait(30);                              // :657
    // :658-705 head creation, each gate taken from its own source mask.
    if global(GVAR_RANK) >= RANK_NORMAL {  // :661 !NHL
        _ = spawn_enemy(0fx, 120fx, 2100, 0, 0, 0, head(0, 135deg, 11.5fx));    // :658-663 I0=2
        _ = spawn_enemy(0fx, 120fx, 2100, 0, 0, 0, head(1, 45deg, 11.5fx));     // :664-669 I0=3
    }
    _ = spawn_enemy(0fx, 120fx, 2100, 0, 0, 0, head(2, 168.75deg, 6fx));       // :670-673 I0=4 all ranks
    _ = spawn_enemy(0fx, 120fx, 2100, 0, 0, 0, head(3, 11.25deg, 6fx));        // :674-677 I0=5 all ranks
    _ = spawn_enemy(0fx, 120fx, 10000, 0, 0, 0, head(4, -90deg, 0.8fx));       // :678-681 I0=6 all ranks
    if global(GVAR_RANK) >= RANK_HARD {    // :685 !HL
        _ = spawn_enemy(0fx, 120fx, 2100, 0, 0, 0, head(5, 178.75deg, 4fx));   // :682-687 I0=7
        _ = spawn_enemy(0fx, 120fx, 2100, 0, 0, 0, head(6, 1.25deg, 4fx));     // :688-693 I0=8
    }
    if global(GVAR_RANK) >= RANK_LUNATIC { // :697 !L
        _ = spawn_enemy(0fx, 120fx, 2100, 0, 0, 0, head(7, 183.75deg, 2.5fx)); // :694-699 I0=7
        _ = spawn_enemy(0fx, 120fx, 2100, 0, 0, 0, head(8, -3.75deg, 2.5fx));  // :700-705 I0=8
    }
    wait(90);                              // :707-708
    spawn at3_loop();                      // :709 @BossCard2_at3() async
    wait(SOURCE_TIMEOUT - 250);            // :710-715 wait(10) loop until the 2280 interrupt
    // :643 interrupt timeout -> Boss3 cleanup (:425-435); next attack is not started.
    kill_all_enemies(KILL_SILENT);         // :425-426 killAllAsync + enmKillAll
    clear_bullets_at(0fx, 144fx, 640fx, 0);    // :431 etClear(640)
    for m in 0..LZ_RING {                  // :435 laserCancel
        var h: int = global(G_LZ + m);
        if lz_alive(h) == 1 { lz_cancel(h); }
    }
    loop { wait(1); }
}

// ---------------------------------------------------------------------------
// Training shell (120-frame opening, staged phase, source enemy carries the attack).
// ---------------------------------------------------------------------------
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1900, 0, 0, 0, boss_main);   // Boss(): movePos(0,128), lifeSet(1900)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_enemy_flag(ENEMY_KILLALL_EXEMPT, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
